/****************************************************************************
 * apps/examples/desktop_companion/ui_main.h
 *
 * UI View Layer — Pure rendering, reads state from app_core.
 ****************************************************************************/

#ifndef UI_MAIN_H
#define UI_MAIN_H

#include "app_core.h"

/* ── One‑time screen creation ────────────────────────────────────────── */

/** Create the modern minimalist full-screen UI layout.
 *  Must be called once after lv_nuttx_init().
 */
void ui_main_create(void);

/* ── Incremental zone updates ────────────────────────────────────────── */

/** Refresh Top Info (Status + Giant Clock). */
void ui_main_update_top(const app_state_t *state);

/** Refresh Center Pet (Face & Animation). */
void ui_main_update_pet(const app_state_t *state);

/** Refresh Bottom Chat (AI Dialog). */
void ui_main_update_chat(const app_state_t *state);

/** Manage Health Popups (Event-driven sliding card). */
void ui_main_update_health(const app_state_t *state);

#endif /* UI_MAIN_H */
