/****************************************************************************
 * apps/examples/desktop_companion/app_core.h
 *
 * Core Application State Machine — Data-Control Layer
 ****************************************************************************/

#ifndef APP_CORE_H
#define APP_CORE_H

#include <stdint.h>
#include <stdbool.h>

/* ── Pet FSM states ──────────────────────────────────────────────────── */

typedef enum {
    PET_AWAKE,      /* Normal: eyes open, proximity = near */
    PET_SLEEPING,   /* Away > 5 s: eyes closed, slow breathe */
    PET_HAPPY,      /* Just arrived: big smile, fast breathe (3 s then → AWAKE) */
    PET_TIRED,      /* When health alert is active */
} pet_state_t;

typedef enum {
    AI_IDLE,        /* Mic off */
    AI_LISTENING,   /* Mic on, capturing */
    AI_THINKING,    /* Processing on server/device */
    AI_SPEAKING,    /* TTS playback active */
} ai_state_t;

typedef enum {
    ALERT_NONE = 0,
    ALERT_SIT,      /* User has been sitting too long */
    ALERT_DRINK,    /* User needs to drink water */
} health_alert_t;

/* ── Global application state ────────────────────────────────────────── */

typedef struct {
    /* Status bar & Clock (Top) */
    struct {
        int  hour;
        int  minute;
        int  second;
        int  year;
        int  month;
        int  day;
        int  weekday;
        float temperature;          /* °C */
        float humidity;             /* % */
        uint32_t lux;               /* Lux */
        bool  wifi_connected;
    } status;

    /* Pet (Center) */
    struct {
        uint16_t  proximity_raw;
        bool      person_present;
        pet_state_t state;
        uint32_t  happy_timer;
    } pet;

    /* AI / Chat (Bottom Dynamic) */
    struct {
        ai_state_t state;
        char      status_text[40];
        char      dialog_buf[1024]; /* ring of last text */
    } ai;

    /* Health Alerts (Bottom Popup) */
    struct {
        health_alert_t active_alert; /* Only one alert active at a time */
    } health;

    /* Internal book‑keeping */
    uint32_t  tick_count;
} app_state_t;

/* ── Public API ──────────────────────────────────────────────────────── */

/** One‑time initialisation. */
void app_core_init(void);

/** Returns a read‑only pointer to the current state. */
const app_state_t *app_core_get_state(void);

/** Force‑set the AI conversation text. */
void app_core_set_ai_text(const char *text);

/** Force‑set the AI state. */
void app_core_set_ai_state(ai_state_t s);

/** Dismiss the currently active health alert (resets its timer). */
void app_core_dismiss_alert(void);

#endif /* APP_CORE_H */

