/****************************************************************************
 * vendor/allwinnertech/chips/r528/drivers/rtos-hal/hal/source/disp2/soc/tianma_config.c
 *
 * Tianma 1080x2160 MIPI DSI panel configuration for R528
 * Timing converted from RK3566 DTSI
 ****************************************************************************/

#include <stdint.h>
#include <hal_clk.h>
#include <hal_gpio.h>
#include "../disp/disp_sys_intf.h"

typedef uint32_t u32;
typedef int32_t  s32;

#include "disp_board_config.h"

/* Panel timing from RK3566 DTSI:
 *   hactive = 1080, vactive = 2160
 *   hfront-porch = 60, hback-porch = 30, hsync-len = 10
 *   vfront-porch = 10, vback-porch = 10, vsync-len = 2
 *   clock-frequency = 145 MHz
 *
 * Allwinner disp2 conversion:
 *   lcd_hspw = hsync-len = 10
 *   lcd_hbp = hspw + hback-porch = 10 + 30 = 40
 *   lcd_hfp = hfront-porch = 60
 *   lcd_ht = hactive + hspw + hbp + hfp = 1080 + 10 + 40 + 60 = 1190
 *   lcd_vspw = vsync-len = 2
 *   lcd_vbp = vspw + vback-porch = 2 + 10 = 12
 *   lcd_vfp = vfront-porch = 10
 *   lcd_vt = vactive + vspw + vbp + vfp = 2160 + 2 + 12 + 10 = 2184
 *
 * 引脚: PD0-PD9(DSI) / PD19(reset) / PD20(PWM backlight)
 */

struct property_t g_lcd0_config[] = {
    /* 基本LCD参数 */
    {
        .name = "lcd_used",
        .type = PROPERTY_INTGER,
        .v.value = 1,
    },
    {
        .name = "lcd_driver_name",
        .type = PROPERTY_STRING,
        .v.str = "tianma",
    },
    {
        .name = "lcd_if",
        .type = PROPERTY_INTGER,
        .v.value = 4,  /* MIPI DSI interface */
    },
    /* 分辨率 */
    {
        .name = "lcd_x",
        .type = PROPERTY_INTGER,
        .v.value = 1080,
    },
    {
        .name = "lcd_y",
        .type = PROPERTY_INTGER,
        .v.value = 2160,
    },
    {
        .name = "lcd_width",
        .type = PROPERTY_INTGER,
        .v.value = 74,  /* Physical width mm */
    },
    {
        .name = "lcd_height",
        .type = PROPERTY_INTGER,
        .v.value = 133, /* Physical height mm */
    },
    {
        .name = "lcd_dclk_freq",
        .type = PROPERTY_INTGER,
        .v.value = 145, /* Pixel clock MHz, matches RK3566 */
    },
    /* DSI 参数 */
    {
        .name = "lcd_dsi_if",
        .type = PROPERTY_INTGER,
        .v.value = LCD_DSI_IF_VIDEO_MODE,  /* Video mode */
    },
    {
        .name = "lcd_dsi_lane",
        .type = PROPERTY_INTGER,
        .v.value = 4,
    },
    {
        .name = "lcd_dsi_format",
        .type = PROPERTY_INTGER,
        .v.value = 0,   /* RGB888 */
    },
    {
