1	/****************************************************************************
2	 * apps/examples/desktop_companion/main.c
3	 *
4	 * Entry point — ties LVGL init, app core, and libuv loop together.
5	 ****************************************************************************/
6	
7	#include <nuttx/config.h>
8	#include <stdio.h>
9	#include <unistd.h>
10	#include <lvgl/lvgl.h>
11	
12	#include "app_core.h"
13	#include "ui_main.h"
14	
15	int main(int argc, FAR char *argv[])
16	{
17	    lv_nuttx_dsc_t  info;
18	    lv_nuttx_result_t result;
19	
20	    /* ── LVGL initialisation ──────────────────────────────────────── */
21	    lv_init();
22	
23	    lv_nuttx_dsc_init(&info);
24	    info.fb_path    = "/dev/fb0";
25	#ifdef CONFIG_INPUT_TOUCHSCREEN
26	    info.input_path = "/dev/input0";
27	#endif
28	
29	    lv_nuttx_init(&info, &result);
30	    if (result.disp == NULL)
31	    {
32	        fprintf(stderr, "[DC] lv_nuttx_init failed\n");
33	        return 1;
34	    }
35	
36	    app_core_init();
37	    ui_main_create();         /* build the 4‑zone UI          */
38	
39	    printf("[DC] Desktop Companion started\n");
40	
41	    /* ── Simple poll loop (same pattern as working screentest) ──── */
42	    while (1)
43	    {
44	        uint32_t idle = lv_timer_handler();
45	        idle = idle ? idle : 1;
46	        usleep(idle * 1000);
47	    }
48	
49	    /* ── Cleanup (never reached) ──────────────────────────────────── */
50	    lv_nuttx_deinit(&result);
51	    lv_deinit();
52	    return 0;
53	}
