339	/* ── 更新：健康弹窗 ──────────────────────────────────────────────────── */
340	
341	void ui_main_update_health(const app_state_t *st)
342	{
343	    if (!st) return;
344	
345	    static health_alert_t last_alert = ALERT_NONE;
346	    health_alert_t curr = st->health.active_alert;
347	
348	    /* 状态没有变，不需要重新执行动画 */
349	    if (curr == last_alert) {
350	        return;
351	    }
352	
353	    if (curr != ALERT_NONE) {
354	        /* 有新提醒，配置内容并向上滑出 */
355	        if (curr == ALERT_SIT) {
356	            lv_label_set_text(g_alert_icon, LV_SYMBOL_REFRESH);
357	            lv_label_set_text(g_alert_text, "你坐得太久啦，起来活动一下吧！");
358	            lv_obj_set_style_bg_color(g_alert_icon, lv_color_hex(0xFF5555), 0);
359	        } else if (curr == ALERT_DRINK) {
360	            lv_label_set_text(g_alert_icon, LV_SYMBOL_TINT);
361	            lv_label_set_text(g_alert_text, "该喝口水啦，保持水分充足！");
362	            lv_obj_set_style_bg_color(g_alert_icon, lv_color_hex(C_ACCENT), 0);
363	        }
364	
365	        /* 弹窗动画: 从 2300 (屏幕外) 滑动到 1850 */
366	        lv_anim_t a;
367	        lv_anim_init(&a);
368	        lv_anim_set_var(&a, g_alert_card);
369	        lv_anim_set_exec_cb(&a, slide_anim_exec);
370	        lv_anim_set_values(&a, SCR_H + 100, 1850);
371	        lv_anim_set_time(&a, 500);
372	        lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
373	        lv_anim_start(&a);
374	    } 
375	    else {
376	        /* 提醒被清除，向下滑动隐藏 */
377	        lv_anim_t a;
378	        lv_anim_init(&a);
379	        lv_anim_set_var(&a, g_alert_card);
380	        lv_anim_set_exec_cb(&a, slide_anim_exec);
381	        lv_anim_set_values(&a, lv_obj_get_y(g_alert_card), SCR_H + 100);
382	        lv_anim_set_time(&a, 400);
383	        lv_anim_set_path_cb(&a, lv_anim_path_ease_in);
384	        lv_anim_start(&a);
385	    }
386	
387	    last_alert = curr;
388	}
