1	/****************************************************************************
2	 * apps/examples/desktop_companion/app_core.c
3	 *
4	 * Core Application State Machine
5	 ****************************************************************************/
6	
7	#include <nuttx/config.h>
8	#include <string.h>
9	#include <stdio.h>
10	#include <lvgl/lvgl.h>
11	
12	#include "app_core.h"
13	#include "ui_main.h"
14	#include "hal_api.h"
15	
16	/* ── Tunables ────────────────────────────────────────────────────────── */
17	
18	#define TICK_MS             1000    /* 1 second per tick */
19	#define SIT_THRESHOLD_S     2700    /* 45 min = 2700 s */
20	#define DRINK_THRESHOLD_S   3600    /* 60 min = 3600 s */
21	#define SLEEP_HYSTERESIS_S  5       /* person away this many ticks → SLEEP */
22	#define HAPPY_DURATION_S    3       /* keep HAPPY face this many ticks */
23	
24	/* ── Private state ───────────────────────────────────────────────────── */
25	
26	static app_state_t  g_state;
27	static bool         g_dirty;                 /* any field changed this tick */
28	static bool         g_pet_dirty;             /* pet state / proximity changed */
29	static bool         g_top_dirty;             /* clock/env changed */
30	static bool         g_chat_dirty;            /* AI text / state changed */
31	static bool         g_health_dirty;          /* health alert changed */
32	
33	static uint32_t     s_sit_seconds = 0;
34	static uint32_t     s_drink_seconds = 0;
35	
36	/* ── Forward declarations ────────────────────────────────────────────── */
37	
38	static void app_timer_cb(lv_timer_t *timer);
39	
40	/* ── Initialisation ──────────────────────────────────────────────────── */
41	
42	void app_core_init(void)
43	{
44	    memset(&g_state, 0, sizeof(g_state));
45	    g_state.pet.state          = PET_AWAKE;
46	    g_state.ai.state           = AI_IDLE;
47	    g_state.health.active_alert = ALERT_NONE;
48	    strcpy(g_state.ai.status_text, "");
49	
50	    /* Default time: 09:30, Jan 1st */
51	    g_state.status.hour = 9;
52	    g_state.status.minute = 30;
53	    g_state.status.month = 1;
54	    g_state.status.day = 1;
55	
56	    g_dirty = g_pet_dirty = g_top_dirty = g_chat_dirty = g_health_dirty = true;
57	
58	    /* Create 1‑second LVGL timer — auto‑integrated with libuv. */
59	    lv_timer_create(app_timer_cb, TICK_MS, NULL);
60	}
61	
62	/* ── State accessors ─────────────────────────────────────────────────── */
63	
64	const app_state_t *app_core_get_state(void)
65	{
66	    return &g_state;
67	}
68	
69	void app_core_set_ai_text(const char *text)
70	{
71	    /* Append to ring buffer */
72	    size_t cur = strlen(g_state.ai.dialog_buf);
73	    size_t tlen = strlen(text);
74	    if (cur + tlen + 3 > sizeof(g_state.ai.dialog_buf))
75	    {
76	        /* Evict oldest half */
77	        char *p = g_state.ai.dialog_buf;
78	        char *mid = p + sizeof(g_state.ai.dialog_buf) / 2;
79	        while (*mid) *p++ = *mid++;
80	        *p = '\0';
81	        cur = strlen(g_state.ai.dialog_buf);
82	    }
83	    if (cur > 0) { strcat(g_state.ai.dialog_buf, "\n"); cur++; }
84	    strcat(g_state.ai.dialog_buf, text);
85	
86	    g_chat_dirty = true;
87	}
88	
89	void app_core_set_ai_state(ai_state_t s)
90	{
91	    if (g_state.ai.state == s) return;
92	    g_state.ai.state = s;
93	    switch (s)
94	    {
95	        case AI_IDLE:      snprintf(g_state.ai.status_text, sizeof(g_state.ai.status_text), "");       break;
96	        case AI_LISTENING: snprintf(g_state.ai.status_text, sizeof(g_state.ai.status_text), "聆听中...");   break;
97	        case AI_THINKING:  snprintf(g_state.ai.status_text, sizeof(g_state.ai.status_text), "思考中...");    break;
98	        case AI_SPEAKING:  snprintf(g_state.ai.status_text, sizeof(g_state.ai.status_text), "讲话中...");    break;
99	    }
100	    g_chat_dirty = true;
101	}
102	
103	void app_core_dismiss_alert(void)
104	{
105	    if (g_state.health.active_alert == ALERT_SIT) {
106	        s_sit_seconds = 0;
107	    } else if (g_state.health.active_alert == ALERT_DRINK) {
108	        s_drink_seconds = 0;
109	    }
110	
111	    g_state.health.active_alert = ALERT_NONE;
112	    if (g_state.pet.state == PET_TIRED) {
113	        g_state.pet.state = PET_AWAKE;
114	        g_pet_dirty = true;
115	    }
116	    g_health_dirty = true;
117	}
118	
119	/* ── Pet FSM update ──────────────────────────────────────────────────── */
120	
121	static void update_pet(bool person_present)
122	{
123	    /* If there is an active alert, pet is forced to be TIRED */
124	    if (g_state.health.active_alert != ALERT_NONE) {
125	        if (g_state.pet.state != PET_TIRED) {
126	            g_state.pet.state = PET_TIRED;
127	            g_pet_dirty = true;
128	        }
129	        return;
130	    }
131	
132	    switch (g_state.pet.state)
133	    {
134	    case PET_AWAKE:
135	    case PET_TIRED: /* Can return to awake if alert was dismissed */
136	        if (!person_present)
137	        {
138	            /* Start counting away‑time */
139	            g_state.pet.happy_timer++;
140	            if (g_state.pet.happy_timer >= SLEEP_HYSTERESIS_S)
141	            {
142	                g_state.pet.state = PET_SLEEPING;
143	                g_state.pet.happy_timer = 0;
144	                g_pet_dirty = true;
145	            }
146	        }
147	        else
148	        {
149	            g_state.pet.happy_timer = 0; /* reset away‑counter */
150	            if (g_state.pet.state != PET_AWAKE) {
151	                g_state.pet.state = PET_AWAKE;
152	                g_pet_dirty = true;
153	            }
154	        }
155	        break;
156	
157	    case PET_SLEEPING:
158	        if (person_present)
159	        {
160	            /* Person just arrived → HAPPY for a few seconds */
161	            g_state.pet.state       = PET_HAPPY;
162	            g_state.pet.happy_timer = HAPPY_DURATION_S;
163	            g_pet_dirty = true;
164	        }
165	        break;
166	
167	    case PET_HAPPY:
168	        if (g_state.pet.happy_timer > 0)
169	        {
170	            g_state.pet.happy_timer--;
171	        }
172	        if (g_state.pet.happy_timer == 0)
173	        {
174	            g_state.pet.state = person_present ? PET_AWAKE : PET_SLEEPING;
175	            g_pet_dirty = true;
176	        }
177	        break;
178	    }
179	}
180	
181	/* ── Health timers ───────────────────────────────────────────────────── */
182	
183	static void update_health(void)
184	{
185	    /* Only trigger one alert at a time to avoid overwhelming the user */
186	    if (g_state.health.active_alert != ALERT_NONE) {
187	        return;
188	    }
189	
190	    bool triggered = false;
191	
192	    s_sit_seconds++;
193	    s_drink_seconds++;
194	
195	    /* Fast-forward for debugging: 1 tick = 1 minute */
196	#ifdef HAL_USE_STUB_SENSORS
197	    s_sit_seconds += 59;
198	    s_drink_seconds += 59;
199	#endif
200	
201	    if (s_sit_seconds >= SIT_THRESHOLD_S)
202	    {
203	        g_state.health.active_alert = ALERT_SIT;
204	        triggered = true;
205	    }
206	    else if (s_drink_seconds >= DRINK_THRESHOLD_S)
207	    {
208	        g_state.health.active_alert = ALERT_DRINK;
209	        triggered = true;
210	    }
211	
212	    if (triggered) {
213	        g_health_dirty = true;
214	    }
215	}
216	
217	/* ── Clock & Env update ───────────────────────────────────────── */
218	
219	static void update_clock_and_env(void)
220	{
221	    /* Simulate clock */
222	    g_state.status.second++;
223	    if (g_state.status.second >= 60)
224	    {
225	        g_state.status.second = 0;
226	        g_state.status.minute++;
227	        g_top_dirty = true; /* Only dirty the UI when minute changes to save CPU */
228	        if (g_state.status.minute >= 60)
229	        {
230	            g_state.status.minute = 0;
231	            g_state.status.hour   = (g_state.status.hour + 1) % 24;
232	        }
233	    }
234	
235	    /* Poll HAL sensors */
236	    {
237	        uint16_t dist;
238	        bool     present;
239	        float    t, h;
240	        uint32_t lx;
241	
242	        hal_sensor_get_proximity(&dist, &present);
243	        hal_sensor_get_env(&t, &h, &lx);
244	
245	        if (g_state.pet.proximity_raw != dist)
246	        {
247	            g_state.pet.proximity_raw = dist;
248	            g_pet_dirty = true;
249	        }
250	        g_state.pet.person_present = present;
251	
252	        /* Add a small deadband to prevent constant UI repainting for small env changes */
253	        if ((int)(g_state.status.temperature*10) != (int)(t*10) ||
254	            (int)(g_state.status.humidity*10)    != (int)(h*10) ||
255	            (int)(g_state.status.lux/10)         != (int)(lx/10))
256	        {
257	            g_state.status.temperature = t;
258	            g_state.status.humidity    = h;
259	            g_state.status.lux         = lx;
260	            g_top_dirty = true;
261	        }
262	    }
263	}
264	
265	/* ── LVGL timer callback ─────────────────────────────────────────────── */
266	
267	static void app_timer_cb(lv_timer_t *timer)
268	{
269	    (void)timer;
270	
271	    g_state.tick_count++;
272	
273	    /* 1. Clock + Environment */
274	    update_clock_and_env();
275	
276	    /* 2. Health timers (may trigger alerts that force pet to be tired) */
277	    update_health();
278	
279	    /* 3. Pet FSM */
280	    update_pet(g_state.pet.person_present);
281	
282	    /* 4. Flush all dirty flags to UI layer */
283	    if (g_top_dirty || g_dirty)     ui_main_update_top(&g_state);
284	    if (g_pet_dirty  || g_dirty)    ui_main_update_pet(&g_state);
285	    if (g_chat_dirty || g_dirty)    ui_main_update_chat(&g_state);
286	    if (g_health_dirty || g_dirty)  ui_main_update_health(&g_state);
287	
288	    g_dirty = g_top_dirty = g_pet_dirty = g_chat_dirty = g_health_dirty = false;
289	}
