/****************************************************************************
 * apps/examples/layouttest/layouttest.c
 *
 * Simple layout demo — beige background, white "test" text at 5 positions.
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <unistd.h>
#include <lvgl/lvgl.h>

#define SCR_W   1080
#define SCR_H   2160
#define C_BG    0xFDF6E3   /* Beige */

static lv_obj_t *make_lbl(lv_obj_t *parent, const char *text, lv_coord_t x, lv_coord_t y)
{
    lv_obj_t *lbl = lv_label_create(parent);
    lv_label_set_text(lbl, text);
    lv_obj_set_style_text_color(lbl, lv_color_hex(0xFFFFFF), 0);
    lv_obj_set_style_text_font(lbl, &lv_font_montserrat_24, 0);
    lv_obj_set_pos(lbl, x, y);
    return lbl;
}

int main(int argc, FAR char *argv[])
{
    lv_nuttx_dsc_t     info;
    lv_nuttx_result_t  result;

    lv_init();
    lv_nuttx_dsc_init(&info);
    info.fb_path    = "/dev/fb0";
    info.input_path = NULL;

    lv_nuttx_init(&info, &result);
    if (!result.disp) {
        fprintf(stderr, "[layouttest] lv_nuttx_init failed\n");
        return 1;
    }

    /* ── Build layout ─────────────────────────────────────────────── */

    lv_obj_t *scr = lv_obj_create(NULL);
    lv_scr_load(scr);
    lv_obj_set_style_bg_color(scr, lv_color_hex(C_BG), 0);
    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
    lv_obj_set_style_pad_all(scr, 0, 0);
    lv_obj_clear_flag(scr, LV_OBJ_FLAG_SCROLLABLE);

    /* 5 positions: TL, TR, C, BR, BL */
    make_lbl(scr, "test", 40, 40);                                          /* TL */
    make_lbl(scr, "test", SCR_W - 40 - 60, 40);                            /* TR */
    make_lbl(scr, "test", SCR_W/2 - 30, SCR_H/2 - 14);                     /* C  */
    make_lbl(scr, "test", 40, SCR_H - 40 - 24);                             /* BL */
    make_lbl(scr, "test", SCR_W - 40 - 60, SCR_H - 40 - 24);               /* BR */

    printf("[layouttest] Running. Press Ctrl-C to exit.\n");

    /* ── LVGL loop ────────────────────────────────────────────────── */
    while (1) {
        uint32_t idle = lv_timer_handler();
        usleep((idle ? idle : 1) * 1000);
    }

    lv_nuttx_deinit(&result);
    lv_deinit();
    return 0;
}

