/****************************************************************************
 * apps/examples/layouttest/layouttest.c
 *
 * Layout demo — powder blue bg, blue border (4 sides), white "test" text.
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <unistd.h>
#include <lvgl/lvgl.h>

#define SCR_W   1080
#define SCR_H   2160
#define C_BG    0xADD8E6   /* 粉蓝色 */
#define C_BORDER 0x1E90FF  /* 亮蓝色边框 */
#define BORDER_W 30         /* 边框宽度 */

static lv_obj_t *make_lbl(lv_obj_t *parent, const char *text, lv_coord_t x, lv_coord_t y)
{
    lv_obj_t *lbl = lv_label_create(parent);
    lv_label_set_text(lbl, text);
    lv_obj_set_style_text_color(lbl, lv_color_hex(0xFFFFFF), 0);
    lv_obj_set_style_text_font(lbl, &lv_font_montserrat_48, 0);
    lv_obj_set_style_transform_zoom(lbl, 256 * 3, 0);  /* 3x zoom */
    lv_obj_set_pos(lbl, x, y);
    return lbl;
}

int main(int argc, FAR char *argv[])
{
    lv_nuttx_dsc_t     info;
    lv_nuttx_result_t  result;

    lv_init();
    lv_nuttx_dsc_init(&info);
    info.fb_path    = "/dev/fb0";
    info.input_path = NULL;

    lv_nuttx_init(&info, &result);
    if (!result.disp) {
        fprintf(stderr, "[layouttest] lv_nuttx_init failed\n");
        return 1;
    }

    /* ── Build layout ─────────────────────────────────────────────── */

    lv_obj_t *scr = lv_obj_create(NULL);
    lv_scr_load(scr);
    lv_obj_set_size(scr, SCR_W, SCR_H);
    lv_obj_set_style_bg_color(scr, lv_color_hex(C_BG), 0);
    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
    lv_obj_set_style_pad_all(scr, 0, 0);
    lv_obj_clear_flag(scr, LV_OBJ_FLAG_SCROLLABLE);

    /* ── 蓝色边框：手动画4条 ───────────────────────────────────────── */
    lv_obj_t *border;

    /* 上边 */
    border = lv_obj_create(scr);
    lv_obj_set_size(border, SCR_W, BORDER_W);
    lv_obj_set_pos(border, 0, 0);
    lv_obj_set_style_bg_color(border, lv_color_hex(C_BORDER), 0);
    lv_obj_set_style_border_width(border, 0, 0);
