    lv_obj_set_style_border_width(border, 0, 0);
    lv_obj_clear_flag(border, LV_OBJ_FLAG_SCROLLABLE);

    /* ── 5 个 "test" 大字 ────────────────────────────────────────── */
    make_lbl(scr, "test", 60, 80);                                            /* TL */
    make_lbl(scr, "test", SCR_W - 60 - 180, 80);                             /* TR */
    make_lbl(scr, "test", SCR_W/2 - 90, SCR_H/2 - 60);                       /* C  */
    make_lbl(scr, "test", 60, SCR_H - 80 - 60);                               /* BL */
